// The needle: a tapered shaft that flattens into a drilled paddle at the top.
// The eye is a true hole (an extruded Shape with a Path hole), so every camera
// -- including the one looking straight down the slot -- sees through it.
// ---------------------------------------------------------------------------
function roundedSlot(halfY, halfZ) {
  const p = new THREE.Path();
  const r = halfZ;                       // fully rounded ends
  const sy = halfY - r;
  p.moveTo(-halfZ, -sy);
  p.lineTo(-halfZ, sy);
  p.absarc(0, sy, r, Math.PI, 0, true);
  p.lineTo(halfZ, -sy);
  p.absarc(0, -sy, r, 0, Math.PI, true);
  return p;
}

