export function buildSet(M) {
  const g = new THREE.Group();

  const deck = new THREE.Mesh(new THREE.BoxGeometry(70, 1.2, 54), M.deck);
  deck.position.set(0, TABLE_Y - 0.6, 0);
  deck.receiveShadow = true;
  g.add(deck);

  // shallow machined ridges, well clear of the deck face so nothing z-fights
  const ridgeMat = M.anodised.clone();
  ridgeMat.color = new THREE.Color(0x15191f);
  for (let i = -8; i <= 8; i++) {
    if (Math.abs(i) < 2) continue;
    const gr = new THREE.Mesh(new THREE.BoxGeometry(70, 0.035, 0.1), ridgeMat);
    gr.position.set(0, TABLE_Y + 0.018, i * 3.1);
    gr.receiveShadow = true;
    g.add(gr);
  }

  // Graded cyclorama: a dark room that still separates silhouettes.
  const room = new THREE.Mesh(
    new THREE.SphereGeometry(120, 32, 24),
    new THREE.ShaderMaterial({
      side: THREE.BackSide, depthWrite: false, fog: false,
      uniforms: {},
      vertexShader: `varying vec3 vP;
        void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `varying vec3 vP;
        void main(){
          float h = clamp(vP.y / 120.0 * 0.5 + 0.5, 0.0, 1.0);
          vec3 top = vec3(0.016, 0.026, 0.038);
          vec3 mid = vec3(0.045, 0.062, 0.080);
          vec3 bot = vec3(0.008, 0.011, 0.016);
          vec3 c = h < 0.5 ? mix(bot, mid, h * 2.0) : mix(mid, top, (h - 0.5) * 2.0);
          // a cool wash behind the rig so the needle reads against something
          float a = atan(vP.z, vP.x);
          c += vec3(0.02, 0.05, 0.06) * pow(max(0.0, cos(a - 2.2)), 6.0) * (1.0 - abs(h - 0.52) * 2.4);
          gl_FragColor = vec4(max(c, 0.0), 1.0);
        }`,
    })
  );
  room.frustumCulled = false;
  g.add(room);

  return g;
}

