// Keys are authored as [time, viewDirection, distance, framedHeightInCm,
// targetOffsetFromEye]: the thing you actually want to control on a macro
// shot is how many centimetres of subject fill the panel.
function resolve(k) {
  const target = EYE.clone().add(k[4] || V(0, 0, 0));
  const pos = target.clone().addScaledVector(k[1].clone().normalize(), k[2]);
  const fov = 2 * Math.atan(k[3] / (2 * k[2])) * 180 / Math.PI;
  return { pos, target, fov };
}

function track(t, keys) {
  let i = 0;
  while (i < keys.length - 2 && t >= keys[i + 1][0]) i++;
  const a = resolve(keys[i]), b = resolve(keys[i + 1]);
  const u = smoother(clamp01((t - keys[i][0]) / (keys[i + 1][0] - keys[i][0])));
  return {
    pos: a.pos.lerp(b.pos, u),
    target: a.target.lerp(b.target, u),
    fov: a.fov + (b.fov - a.fov) * u,
  };
}

