// One phalanx: a tapered machined link, slimmer at the far end, with a dark
// knuckle at its root. Slab-sided rather than tubular, so the fingers read as
// separate links instead of a bundle of pipes.
function phalanx(M, len, r, opts = {}) {
  const g = new THREE.Group();
  const r2 = r * (opts.taper ?? 0.82);

  const core = new THREE.Mesh(
    new THREE.CylinderGeometry(r2 * 0.92, r * 0.92, len * 0.98, 14, 1), M.alu);
  core.rotation.z = -Math.PI / 2;
  core.position.x = len * 0.49;
  core.scale.set(1, 1, 0.74);          // flatten across the finger
  core.castShadow = true;
  g.add(core);

  // dark structural web along the underside
  const web = new THREE.Mesh(new THREE.BoxGeometry(len * 0.86, r * 0.95, r * 0.9), M.polymer);
  web.position.set(len * 0.5, -r * 0.3, 0);
  web.castShadow = true;
  g.add(web);

  // knuckle
  const hub = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.86, r * 0.86, r * 1.45, 14), M.anodised);
  hub.rotation.x = Math.PI / 2;
  hub.castShadow = true;
  g.add(hub);
  if (opts.accent) {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(r * 0.5, r * 0.055, 5, 14), M.accent);
    ring.position.z = r * 0.76;
    g.add(ring);
  }

  // rubberised pad on the gripping (−Y) face of the distal segment
  if (opts.pad) {
    const pad = new THREE.Mesh(new THREE.BoxGeometry(len * 0.6, r * 0.42, r * 0.95), M.grip);
    pad.position.set(len * 0.56, -r * 0.72, 0);
    g.add(pad);
    const nail = new THREE.Mesh(new THREE.SphereGeometry(r2 * 0.88, 12, 10), M.alu);
    nail.position.x = len * 0.97;
    nail.scale.set(0.8, 1, 0.74);
    nail.castShadow = true;
    g.add(nail);
  }
  return g;
}

