    // without ever being able to slip back out around the plate.
    const ax = Math.abs(x - N.x);
    const ay = Math.abs(y - N.eyeCY);
    if (threaded && ax < 0.34 && ay < 0.62 && Math.abs(z) < 0.55) {
      const wx = 1 - Math.min(1, Math.max(0, (ax - 0.10) / 0.24));
      const wy = 1 - Math.min(1, Math.max(0, (ay - 0.30) / 0.32));
      const w = wx * wy;
      const d = slotDist(y, z);
      const inner = SLOT_R - r;
      if (d > inner) {
        const cy = Math.max(SLOT_Y0, Math.min(SLOT_Y1, y));
        const s = inner / Math.max(d, 1e-6);
        y += (cy + (y - cy) * s - y) * w;
        z += (z * s - z) * w;
